begin;
update public.questions set body = 'Consider the following statements about how animals are adapted to climate:', body_hi = 'जीवों के जलवायु के प्रति अनुकूलन के बारे में निम्नलिखित कथनों पर विचार कीजिए:', question_data = '{"statements": ["Bergmann''s rule states that among related warm-blooded animals, those in colder climates tend to have smaller bodies.", "The kangaroo rat of North American deserts can meet its water needs from the internal oxidation of fat, without drinking water.", "Polar mammals such as seals have only a thin layer of fat under the skin, which helps them shed body heat."], "statements_hi": ["बर्गमान का नियम कहता है कि संबंधित नियततापी जीवों में ठंडी जलवायु वालों का शरीर छोटा होता है।", "उत्तरी अमेरिका के मरुस्थलों का कंगारू चूहा पानी पिए बिना, वसा के आंतरिक ऑक्सीकरण से अपनी पानी की ज़रूरत पूरी कर सकता है।", "सील जैसे ध्रुवीय स्तनधारियों की त्वचा के नीचे वसा की केवल पतली परत होती है, जो उन्हें शरीर की गर्मी बाहर निकालने में मदद करती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, explanation = 'Only statement 2 is correct: NCERT''s example of a desert mammal that gets its water from metabolism and concentrates its urine to save it. Statement 1 reverses Bergmann''s rule: related warm-blooded animals are larger in colder climates, since a larger body has less surface per unit volume and so loses heat more slowly. Statement 3 is wrong: seals, whales and walruses have a thick layer of blubber under the skin, which insulates them in icy water and also stores energy; shedding heat is the last thing a polar mammal needs.', explanation_hi = 'केवल कथन 2 सही है: यह NCERT का उस मरुस्थलीय स्तनधारी का उदाहरण है जो चयापचय से पानी पाता है और पानी बचाने के लिए अपने मूत्र को गाढ़ा करता है। कथन 1 बर्गमान के नियम को उलट देता है: संबंधित नियततापी जीव ठंडी जलवायु में बड़े होते हैं, क्योंकि बड़े शरीर में प्रति इकाई आयतन सतह कम होती है और इसलिए गर्मी धीरे-धीरे खोती है। कथन 3 गलत है: सील, व्हेल और वॉलरस की त्वचा के नीचे वसा (blubber) की मोटी परत होती है, जो बर्फ़ीले पानी में उन्हें ऊष्मारोधन देती है और ऊर्जा भी संचित करती है; ध्रुवीय स्तनधारी को गर्मी बाहर निकालने की सबसे कम ज़रूरत होती है।', source_citation = 'NCERT Class XII, Biology -- Organisms and Populations (adaptations).', concept_group_id = 'env-bergmann-rule-adaptations', updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'env-bergmann-allen-rules';
update public.questions set body = 'Consider the following statements about fruit bats (flying foxes) in India:', body_hi = 'भारत में फल-चमगादड़ों (flying foxes) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', question_data = '{"statements": ["They are important pollinators and seed dispersers of many tropical trees.", "Fruit bats of the genus Pteropus are natural reservoirs of the Nipah virus.", "Bats and flying squirrels are the only mammals capable of true, powered flight."], "statements_hi": ["ये कई उष्णकटिबंधीय पेड़ों के महत्त्वपूर्ण परागणकर्ता और बीज-प्रसारक हैं।", "Pteropus वंश के फल-चमगादड़ निपाह वायरस के प्राकृतिक भंडार (reservoir) हैं।", "चमगादड़ और उड़न गिलहरियाँ ही वास्तविक, संचालित उड़ान (powered flight) में सक्षम एकमात्र स्तनधारी हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, explanation = 'Statements 1 and 2 are correct. Fruit bats pollinate and spread the seeds of trees such as the silk cotton, wild banana and durian, often over long distances, which makes them important for forest regeneration. The Indian flying fox (Pteropus medius) is a natural host of the Nipah virus, which has caused outbreaks in Kerala and West Bengal; the virus spreads to people through fruit or palm sap contaminated by bats, which is why the answer to Nipah is surveillance and safe food, not culling bats. Statement 3 is wrong: bats are the only mammals capable of true, powered flight; flying squirrels (and the flying lemur) only glide, using a membrane of skin stretched between their limbs.', explanation_hi = 'कथन 1 और 2 सही हैं। फल-चमगादड़ सेमल, जंगली केले और ड्यूरियन जैसे पेड़ों का परागण करते हैं और उनके बीज प्रायः दूर-दूर तक फैलाते हैं, जिससे वे वनों के पुनर्जनन के लिए महत्त्वपूर्ण हैं। भारतीय फल-चमगादड़ (Pteropus medius) निपाह वायरस का प्राकृतिक मेज़बान है, जिसने केरल और पश्चिम बंगाल में प्रकोप फैलाए हैं; वायरस चमगादड़ों से दूषित फल या ताड़ के रस के ज़रिए लोगों तक पहुँचता है, इसलिए निपाह का उत्तर निगरानी और सुरक्षित भोजन है, चमगादड़ों को मारना नहीं। कथन 3 गलत है: चमगादड़ ही वास्तविक, संचालित उड़ान में सक्षम एकमात्र स्तनधारी हैं; उड़न गिलहरियाँ (और उड़न लीमर) अपने अंगों के बीच फैली त्वचा की झिल्ली के सहारे केवल सरकती (glide) हैं।', source_citation = 'Zoological Survey of India -- bats of India; National Centre for Disease Control / ICMR-NIV -- Nipah virus in Pteropus bats; WHO -- Nipah virus fact sheet.', concept_group_id = 'env-fruit-bats-nipah', updated_at = now() where exam_category = 'upsc' and status = 'draft' and concept_group_id = 'env-fruit-bats-vermin';
commit;
select concept_group_id, status from public.questions where concept_group_id in ('env-bergmann-rule-adaptations','env-fruit-bats-nipah','env-bergmann-allen-rules','env-fruit-bats-vermin');
